mapper.select:
SELECT t1.`user_name` FROM `camera_patrol_record` t1
t1.`camera_patrol_line_id` = #{cameraPatrolLineId}
GROUP BY t1.`user_id`

SELECT
COALESCE(SUM(cpr.`abnormal_num`),0) as abnormal_num
FROM
`camera_patrol_record` cpr


        and cpr.`patrol_time` >= #{param.period.begin}


        and cpr.`patrol_time` <= #{param.period.end}

SELECT
count(cpr.`id`) as record_num
FROM
`camera_patrol_record` cpr


        and cpr.`patrol_time` >= #{param.period.begin}


        and cpr.`patrol_time` <= #{param.period.end}

SELECT DATE_FORMAT( patrol_time, '%H' ) AS period, COUNT( 1 ) AS total_num FROM `camera_patrol_record`
and `patrol_time` >= #{param.period.begin}
and `patrol_time` <= #{param.period.end}
GROUP BY DATE_FORMAT(`patrol_time`,'%H')

SELECT t1.`user_id`, t1.`user_name`, COUNT(t2.`id`) as patrol_camera_count FROM `camera_patrol_record` t1 INNER JOIN `camera_patrol_record_device` t2 on t1.`id` = t2.`camera_patrol_record_id`
t2.`status` = 'CAMERA_PATROL_COMPLETE'
and t1.`patrol_time` >= #{param.period.begin}
and t1.`patrol_time` <= #{param.period.end}
GROUP BY t1.`user_id`,t1.`user_name`
